CREATE TABLE "dest_traits" (
	"dest_id" uuid NOT NULL,
	"trait_id" text NOT NULL,
	"value" double precision NOT NULL,
	"evidence" text,
	"confidence" real,
	"version" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "dest_traits_pkey" PRIMARY KEY("dest_id","trait_id"),
	CONSTRAINT "dest_traits_confidence_check" CHECK ("dest_traits"."confidence" is null or ("dest_traits"."confidence" >= 0 and "dest_traits"."confidence" <= 1))
);
